1437	/// Time one sample (`inner` back-to-back calls), divide down to a
1438	/// per-call value in **picoseconds**, and record it, clamping at
1439	/// the histogram bounds — a suspend-inflated or wedged sample
1440	/// must not panic a long run ([`crate::report::warn_invalid`] flags it instead).
1441	///
1442	/// - The seam dither (a random sub-quantum spin before the timer
1443	///   pair, outside the timed interval) stops the run's aggregate
1444	///   means from carrying a coherent ±quantum phase bias — up to
1445	///   ~±2% on fast benches (see
1446	///   notes/design.md#dithering-random-phase-injection).
1447	fn record_sample<B: Bench>(
1448	    bench: &mut B,
1449	    inner: u64,
1450	    pipeline: &mut BlockPipeline,
1451	    dither: &mut Dither,
1452	) {
1453	    dither.spin();
1454	    let start = std::time::Instant::now();
1455	    for _ in 0..inner {
1456	        black_box(bench.step());
1457	    }
1458	    let elapsed_ps = start.elapsed().as_nanos().saturating_mul(1000);
1459	    pipeline.push(round_elapsed_ps(elapsed_ps, inner));
1460	}
