1462	/// Per-call value: `elapsed_ps / inner`, rounded to nearest, in
1463	/// u128 so an hours-long suspend-inflated sample can't overflow
1464	/// the ×1000 ns→ps conversion; the cast clamps at u64::MAX and
1465	/// `saturating_record` clamps again at the histogram bound.
1466	fn round_elapsed_ps(elapsed_ps: u128, inner: u64) -> u64 {
1467	    let inner = inner as u128;
1468	    ((elapsed_ps + inner / 2) / inner).min(u64::MAX as u128) as u64
1469	}
