1499	        let boot_s = (boottime_ns() - self.boot_ns) as f64 / 1e9;
1500	        let mono_s = self.mono.elapsed().as_nanos() as f64 / 1e9;
1501	        boot_s - mono_s
1502	    }
1503	}
