1505	/// Current `CLOCK_BOOTTIME` reading in nanoseconds.
1506	fn boottime_ns() -> u64 {
1507	    let mut ts = libc::timespec {
1508	        tv_sec: 0,
1509	        tv_nsec: 0,
1510	    };
1511	    // SAFETY: clock_gettime only writes `ts`; CLOCK_BOOTTIME is
1512	    // always valid on Linux.
1513	    let rc = unsafe { libc::clock_gettime(libc::CLOCK_BOOTTIME, &mut ts) };
1514	    assert_eq!(rc, 0, "clock_gettime(CLOCK_BOOTTIME) failed");
1515	    ts.tv_sec as u64 * 1_000_000_000 + ts.tv_nsec as u64
1516	}
